import pdfplumber
import re
import datetime
from typing import Dict, Any, List, Optional

class ITTSalaryParser:
    """
    Robust parser for ITT ITALIA S.r.l. Salary Slips (Busta Paga).
    Implements a zone-based strategy for multi-page documents:
    - Top/Bottom Zones: Metadata & Header/Footer aggregation.
    - Middle Zone: Variable length Payroll Table (concatenated).
    - End Page: Attendance Data.
    """

    @staticmethod
    def parse_italian_float(val: str) -> float:
        """Converts IT format (1.234,56 or 12,00-) to Python float."""
        if not val: return 0.0
        if isinstance(val, (float, int)): return float(val)
        val = str(val).strip()
        if not val: return 0.0

        # Handle trailing negative sign common in SAP/Zucchetti systems
        if val.endswith("-"):
            val = '-' + val[:-1]

        # Remove dots (thousands separator) and replace comma with dot (decimal)
        clean = val.replace(".", "").replace(",", ".")
        try:
            return float(clean)
        except ValueError:
            return 0.0

    @classmethod
    def parse(cls, file_path: str) -> Dict[str, Any]:
        extracted = {
            "employer": "ITT ITALIA S.r.l.",
            "employee_name": "Unknown",
            "employee_id": "Unknown",
            "month_reference": "Unknown",
            "date": datetime.date.today(),
            "net_income": 0.0,
            "total_earnings": 0.0,
            "total_deductions": 0.0,
            "contract_hours": 0.0,
            "items": [],
            "leaves": [],
            "fiscal_data": {},
            "attendance": []
        }

        metadata_accumulator = {}
        all_payroll_rows = []
        attendance_entries = []

        with pdfplumber.open(file_path) as pdf:
            for page in pdf.pages:
                page_text = page.extract_text() or ""

                # 1. Identify Page Type
                if "Data entrata" in page_text and "Ora entrata" in page_text:
                    # ATTENDANCE PAGE
                    cls._extract_attendance_data(page, attendance_entries)
                else:
                    # STANDARD PAYROLL PAGE
                    # A. Header & Footer (Metadata)
                    # Define crop zones (approximate percentages based on A4)
                    width, height = page.width, page.height

                    # Top 20% for Header
                    header_crop = page.crop((0, 0, width, height * 0.20))
                    header_text = header_crop.extract_text()
                    if header_text:
                        cls._extract_key_values(header_text, metadata_accumulator)

                    # Bottom 20% for Footer (Totals, Leaves, Net)
                    footer_crop = page.crop((0, height * 0.80, width, height))
                    footer_text = footer_crop.extract_text()
                    if footer_text:
                        cls._extract_key_values(footer_text, metadata_accumulator)
                        # Also parse complex footer structures (Leaves, Fiscal) from text
                        cls._parse_footer_special(footer_text, extracted) 

                    # B. Middle Table (Payroll Rows)
                    # Crop middle section
                    middle_crop = page.crop((0, height * 0.20, width, height * 0.80))

                    # Strategy: Use explicit columns if possible, or text-based fallback
                    # Based on standard ITT layout, columns are roughly:
                    # Cod | Descrizione | Ore/GG | Dato Base | Competenze | Trattenute
                    # We'll use text extraction line-by-line which is safer for varying layouts than rigid explicit_vertical_lines unless we know them exactly.
                    middle_text = middle_crop.extract_text()
                    if middle_text:
                        cls._parse_payroll_text(middle_text, all_payroll_rows)

        # Map accumulated data to final structure
        cls._map_metadata(metadata_accumulator, extracted)
        extracted["items"] = all_payroll_rows
        extracted["attendance"] = attendance_entries

        return extracted

    @classmethod
    def _extract_key_values(cls, text: str, accumulator: Dict[str, Any]):
        """Parses standard Key: Value pairs from headers/footers."""
        # Employee Name
        name_match = re.search(r"Sig\.\s+([A-Z\s]+)\s+\d{4}", text)
        if name_match: accumulator["employee_name"] = name_match.group(1).strip()

        # Employee ID
        id_match = re.search(r"C\.I\.D\s.*?(\d{4})", text)
        if id_match: accumulator["employee_id"] = id_match.group(1)

        # Period
        period_match = re.search(r"([A-Z][a-z]+\s20\d{2})\s+Pagina", text)
        if period_match: accumulator["month_reference"] = period_match.group(1)

        # Net Pay
        net_match = re.search(r"Netto in busta\s+([\d\.]+,\d{2})", text)
        if net_match: accumulator["net_income"] = cls.parse_italian_float(net_match.group(1))

        # Contract Hours
        hours_match = re.search(r"Ore Contr\.\s+(\d+)", text)
        if hours_match: accumulator["contract_hours"] = float(hours_match.group(1))

        # Totals
        tot_header_match = re.search(r"Tot\.Comp\.\s+Tot\.Trat\.", text)
        if tot_header_match:
            # Look for the numbers in the same or next line
            # This regex looks for two currency values close to each other
            nums = re.findall(r"([\d\.]+,\d{2})", text[tot_header_match.end():])
            if len(nums) >= 2:
                accumulator["total_earnings"] = cls.parse_italian_float(nums[0])
                accumulator["total_deductions"] = cls.parse_italian_float(nums[1])

    @classmethod
    def _parse_payroll_text(cls, text: str, rows: List[Dict[str, Any]]):
        """Parses the middle section text into payroll rows."""
        lines = text.split('\n')
        parsing = False

        for line in lines:
            if "Cod. Descrizione" in line:
                parsing = True
                continue
            if not parsing:
                continue

            # Stop if we hit footer markers leaking into middle crop
            if "Tot.Comp." in line or "Netto in busta" in line:
                break

            line = line.strip()
            if not line: continue

            # Parse Row
            parts = line.split()
            if len(parts) > 1:
                # Heuristic parsing
                code = parts[0]

                # If code is not alphanumeric short code, skip (it's likely noise)
                if len(code) > 6: continue 

                # Reverse find numbers
                numbers = []
                desc_end_index = len(parts)

                for i in range(len(parts) - 1, 0, -1):
                    part = parts[i]
                    # Match Italian float or "X" placeholder
                    if re.match(r"^[\d\.]+,\d{2,4}-?$", part) or part == "X":
                         if part != "X":
                            numbers.insert(0, cls.parse_italian_float(part))
                         desc_end_index = i
                    else:
                        break

                description = " ".join(parts[1:desc_end_index])

                is_deduction = code.startswith("/") or "Tratt" in line or "Addiz" in line or code in ["076B", "0786"]

                item = {
                    "code": code,
                    "description": description,
                    "quantity": 0.0,
                    "base_data": 0.0,
                    "earnings": 0.0,
                    "deductions": 0.0,
                    "type": "Deduction" if is_deduction else "Earning"
                }

                # Assign values based on position/count
                # Standard Columns: Qty | Base | Earnings | Deductions
                # But typically only 3 numeric columns appear populated max per row
                if is_deduction:
                    if len(numbers) >= 1: item["deductions"] = numbers[-1]
                    if len(numbers) >= 2: item["base_data"] = numbers[-2]
                else:
                    if len(numbers) >= 1: item["earnings"] = numbers[-1]
                    if len(numbers) >= 2: item["base_data"] = numbers[-2]
                    if len(numbers) >= 3: item["quantity"] = numbers[-3]

                rows.append(item)

    @classmethod
    def _parse_footer_special(cls, text: str, extracted: Dict[str, Any]):
        """Parses Leaves and Fiscal Data from footer text."""
        # --- LEAVES ---
        cats = ["Ferie", "BancaOr", "ExFes/Rol", "Fless."]
        db_cat_map = {"Ferie": "Ferie", "BancaOr": "Banca Ore", "ExFes/Rol": "ROL/ExFest", "Fless.": "Flessibilita"}

        row_patterns = {
            "previous_residue": r"Res\.A\.P\.\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "accrued": r"Mat\.Anno\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "used": r"Goduto\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "remaining": r"Residuo\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)"
        }

        # Only parse if we haven't already (or overwrite with latest page data which is usually cumulative)
        found_leaves = False
        for r_type, regex in row_patterns.items():
            match = re.search(regex, text)
            if match:
                found_leaves = True
                vals = match.groups()
                for i, cat in enumerate(cats):
                    if i < len(vals):
                        # Find existing leave entry or create new
                        mapped_cat = db_cat_map.get(cat, cat)
                        existing = next((l for l in extracted["leaves"] if l["leave_type"] == mapped_cat), None)
                        val_float = cls.parse_italian_float(vals[i])

                        if existing:
                            existing[r_type] = val_float
                        else:
                            new_leave = {"leave_type": mapped_cat, "previous_residue": 0, "accrued": 0, "used": 0, "remaining": 0}
                            new_leave[r_type] = val_float
                            extracted["leaves"].append(new_leave)

        # --- FISCAL ---
        if "Imp.Fisc" in text:
            fiscal = extracted["fiscal_data"]
