                        date_obj = datetime.datetime.strptime(date_str, "%d.%m.%Y").date()
                    except:
                        continue

                    if len(row) >= 4:
                         time_out = row[3] # Assuming [Date, TimeIn, DateOut, TimeOut]
                    elif len(row) == 3:
                         time_out = row[2] # Assuming [Date, TimeIn, TimeOut]

                    attendance_entries.append({
                        "date": date_obj,
                        "entry_time": time_in,
                        "exit_time": time_out
                    })

    @classmethod
    def _map_metadata(cls, metadata: Dict[str, Any], extracted: Dict[str, Any]):
        """Transfers metadata to the final extracted dict."""
