import pdfplumber
import re
import datetime
from typing import Dict, Any, List

class ITTSalaryParser:
    """
    Robust parser for ITT ITALIA S.r.l. Salary Slips using pdfplumber.
    Follows a State-Based Approach for identification and parsing.
    """

    @staticmethod
    def parse_italian_float(val: str) -> float:
        """Converts IT format (1.234,56 or 12,00-) to Python float."""
        if not val: return 0.0
        val = val.strip()
        # Handle trailing negative sign common in SAP/Zucchetti systems
        if val.endswith("-"):
            val = '-' + val[:-1]

        # Remove dots (thousands separator) and replace comma with dot (decimal)
        clean = val.replace(".", "").replace(",", ".")
        try:
            return float(clean)
        except ValueError:
            return 0.0

    @classmethod
    def parse(cls, file_path: str) -> Dict[str, Any]:
        extracted = {
            "employer": "ITT ITALIA S.r.l.",
            "employee_name": "Unknown",
            "employee_id": "Unknown",
            "month_reference": "Unknown",
            "date": datetime.date.today(),
            "net_income": 0.0,
            "total_earnings": 0.0,
            "total_deductions": 0.0,
            "contract_hours": 0.0,
            "items": [],
            "leaves": [],
            "fiscal_data": {},
            "attendance": []
        }

        with pdfplumber.open(file_path) as pdf:
            # 1. Global Identification: Scan all text for header info
            full_text = ""
            for page in pdf.pages:
                full_text += (page.extract_text() or "") + "\n"

            cls._extract_header_info(full_text, extracted)

            # 2. Page Type Detection and Parsing
            for page in pdf.pages:
                text = page.extract_text() or ""
                if "Cod. Descrizione" in text:
                    cls._process_financial_page(text, extracted)
                if "Data entrata" in text:
                    cls._process_attendance_page(text, extracted)

        return extracted

    @classmethod
    def _extract_header_info(cls, text: str, extracted: Dict[str, Any]):
        """Extracts global info like Name, Period, Net Pay."""
        # Employee Name
        name_match = re.search(r"Sig\.\s+([A-Z\s]+)\s+\d{4}", text)
        if name_match:
            extracted["employee_name"] = name_match.group(1).strip()

        # Employee ID (CID)
        id_match = re.search(r"C\.I\.D\s.*?(\d{4})", text)
        if id_match:
            extracted["employee_id"] = id_match.group(1)

        # Period (Month Year)
        period_match = re.search(r"([A-Z][a-z]+\s20\d{2})\s+Pagina", text)
        if period_match:
            extracted["month_reference"] = period_match.group(1)
            # Try to parse date from string (e.g., "Ottobre 2025")
            try:
                # Need italian locale or manual mapping
                months = {
                    "Gennaio": 1, "Febbraio": 2, "Marzo": 3, "Aprile": 4, "Maggio": 5, "Giugno": 6,
                    "Luglio": 7, "Agosto": 8, "Settembre": 9, "Ottobre": 10, "Novembre": 11, "Dicembre": 12
                }
                parts = extracted["month_reference"].split()
                if len(parts) == 2 and parts[0] in months:
                    extracted["date"] = datetime.date(int(parts[1]), months[parts[0]], 1)
            except:
                pass

        # Net Pay
        net_match = re.search(r"Netto in busta\s+([\d\.]+,\d{2})", text)
        if net_match:
            extracted["net_income"] = cls.parse_italian_float(net_match.group(1))

        # Contract Hours
        hours_match = re.search(r"Ore Contr\.\s+(\d+)", text)
        if hours_match:
            extracted["contract_hours"] = float(hours_match.group(1))

        # Totals
        tot_header_pattern = r"Tot\.Comp\.\s+Tot\.Trat\."
        tot_header_match = re.search(tot_header_pattern, text)
        if tot_header_match:
            after_header = text[tot_header_match.end():].strip()
            # Find first line with numbers
            lines_after = after_header.split('\n')
            for l in lines_after:
                nums = re.findall(r"[\d\.]+,\d{2}", l)
                if len(nums) >= 2:
                    extracted["total_earnings"] = cls.parse_italian_float(nums[0])
                    extracted["total_deductions"] = cls.parse_italian_float(nums[1])
                    break

    @classmethod
    def _process_financial_page(cls, text: str, extracted: Dict[str, Any]):
        """Handles Page 1: Items, Vacation Grid, Tax."""
        lines = text.split('\n')

        # --- A. PARSE LINE ITEMS ---
        parsing_table = False
        for line in lines:
            if "Cod. Descrizione" in line:
                parsing_table = True
                continue
            if "Tot.Comp." in line or "Ferie" in line:
                parsing_table = False

            if parsing_table and line.strip():
                # Regex to capture: Code, Description, Quantity, Base, Values
                # Attempt to split by spacing logic
                parts = line.split()
                if len(parts) > 2:
                    code = parts[0]

                    # Identify numbers at the end of the line
                    numbers = []
                    desc_end_index = len(parts)

                    # Iterate backwards to find all numbers
                    for i in range(len(parts) - 1, 0, -1):
                        part = parts[i]
                        if re.match(r"^[\d\.]+,\d{4}-?$", part) or re.match(r"^[\d\.]+,\d{2}-?$", part) or part == "X":
                            if part != "X":
                                numbers.insert(0, cls.parse_italian_float(part))
                            desc_end_index = i
                        else:
                            break

                    description = " ".join(parts[1:desc_end_index])

                    # Determine type
                    is_deduction = code.startswith("/") or "Tratt" in line or "Addiz" in line or code in ["076B", "0786"]

                    item = {
                        "code": code,
                        "description": description,
                        "quantity": 0.0,
                        "base_data": 0.0,
                        "earnings": 0.0,
                        "deductions": 0.0,
                        "type": "Deduction" if is_deduction else "Earning"
                    }

                    # Assign numbers based on heuristics (usually Quantity, Base, Amount)
                    # But columns are: Ore/GG | Dato Base | Competenze | Trattenute
                    # If deduction, amount is in Trattenute (last col). If earning, in Competenze.

                    if is_deduction:
                         if len(numbers) >= 1: item["deductions"] = numbers[-1]
                         if len(numbers) >= 2: item["base_data"] = numbers[-2]
                    else:
                         if len(numbers) >= 1: item["earnings"] = numbers[-1]
                         if len(numbers) >= 2: item["base_data"] = numbers[-2]
                         if len(numbers) >= 3: item["quantity"] = numbers[-3]

                    extracted["items"].append(item)

        # --- B. PARSE VACATION GRID ---
        cats = ["Ferie", "BancaOr", "ExFes/Rol", "Fless."]
        # Re-mapping to match DB model
        db_cat_map = {"Ferie": "Ferie", "BancaOr": "Banca Ore", "ExFes/Rol": "ROL/ExFest", "Fless.": "Flessibilita"}

        row_patterns = {
            "previous_residue": r"Res\.A\.P\.\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "accrued": r"Mat\.Anno\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "used": r"Goduto\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "remaining": r"Residuo\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)"
        }

        grid_data = {c: {} for c in cats}
        for r_type, regex in row_patterns.items():
            match = re.search(regex, text)
            if match:
                vals = match.groups()
                for i, cat in enumerate(cats):
                    if i < len(vals):
                        grid_data[cat][r_type] = cls.parse_italian_float(vals[i])

        for cat, data in grid_data.items():
            # Only add if there is data
            if any(v != 0 for v in data.values()):
                extracted["leaves"].append({
                    "leave_type": db_cat_map.get(cat, cat),
                    "previous_residue": data.get("previous_residue", 0.0),
                    "accrued": data.get("accrued", 0.0),
                    "used": data.get("used", 0.0),
                    "remaining": data.get("remaining", 0.0)
                })

        # --- C. PARSE TAX & TFR ---
        # Fiscal Data structure
        fiscal = {
            "taxable_income": 0.0,
            "gross_tax": 0.0,
            "net_tax": 0.0,
            "tfr_month": 0.0,
            "tfr_fund": 0.0
        }

        imp_fisc = re.search(r"Imp\.Fisc.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
        if imp_fisc: fiscal["taxable_income"] = cls.parse_italian_float(imp_fisc.group(1))

        imp_lord = re.search(r"Imposta L\.\s+(\d[\d\.]*,\d{2})", text) # Imposta Lorda often abbreviated
        if imp_lord: fiscal["gross_tax"] = cls.parse_italian_float(imp_lord.group(1))

        imp_net = re.search(r"Imposta Net.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
        if imp_net: fiscal["net_tax"] = cls.parse_italian_float(imp_net.group(1))

        tfr_month = re.search(r"TFR Mese\s+([\d\.]*,\d{2})", text)
        if tfr_month: fiscal["tfr_month"] = cls.parse_italian_float(tfr_month.group(1))

        tfr_fund = re.search(r"Q\.TFR Fdo\s+([\d\.]*,\d{2})", text)
        if tfr_fund: fiscal["tfr_fund"] = cls.parse_italian_float(tfr_fund.group(1))

        extracted["fiscal_data"] = fiscal

    @classmethod
    def _process_attendance_page(cls, text: str, extracted: Dict[str, Any]):
        """Handles Page 2/3: Attendance logs."""
        lines = text.split('\n')
        start_reading = False

        for line in lines:
            if "Data entrata" in line:
                start_reading = True
                continue

            if start_reading:
                # Regex for: 01.10.2025 08:00:00 ...
                match = re.search(r"(\d{2}\.\d{2}\.\d{4})\s+(\d{2}:\d{2}:\d{2})\s.*?(\d{2}:\d{2}:\d{2})?", line)
                if match:
                    d_str = match.group(1)
                    try:
                         date_obj = datetime.datetime.strptime(d_str, "%d.%m.%Y").date()
                    except:
                         continue

                    entry = match.group(2)
                    exit_ = match.group(3) if match.group(3) else None

                    extracted["attendance"].append({
                        "date": date_obj,
                        "entry_time": entry,
                        "exit_time": exit_
                    })

import pdfplumber
import re
import datetime
from typing import Dict, Any, List, Optional

class ITTSalaryParser:
    """
    Robust parser for ITT ITALIA S.r.l. Salary Slips (Busta Paga).
    Implements a zone-based strategy for multi-page documents:
    - Top/Bottom Zones: Metadata & Header/Footer aggregation.
    - Middle Zone: Variable length Payroll Table (concatenated).
    - End Page: Attendance Data.
    """

    @staticmethod
    def parse_italian_float(val: str) -> float:
        """Converts IT format (1.234,56 or 12,00-) to Python float."""
        if not val: return 0.0
        if isinstance(val, (float, int)): return float(val)
        val = str(val).strip()
        if not val: return 0.0

        # Handle trailing negative sign common in SAP/Zucchetti systems
        if val.endswith("-"):
            val = '-' + val[:-1]

        # Remove dots (thousands separator) and replace comma with dot (decimal)
        clean = val.replace(".", "").replace(",", ".")
        try:
            return float(clean)
        except ValueError:
            return 0.0

    @classmethod
    def parse(cls, file_path: str) -> Dict[str, Any]:
        extracted = {
            "employer": "ITT ITALIA S.r.l.",
            "employee_name": "Unknown",
            "employee_id": "Unknown",
            "month_reference": "Unknown",
            "date": datetime.date.today(),
            "net_income": 0.0,
            "total_earnings": 0.0,
            "total_deductions": 0.0,
            "contract_hours": 0.0,
            "items": [],
            "leaves": [],
            "fiscal_data": {},
            "attendance": []
        }

        metadata_accumulator = {}
        all_payroll_rows = []
        attendance_entries = []

        with pdfplumber.open(file_path) as pdf:
            for page in pdf.pages:
                page_text = page.extract_text() or ""

                # 1. Identify Page Type
                if "Data entrata" in page_text and "Ora entrata" in page_text:
                    # ATTENDANCE PAGE
                    cls._extract_attendance_data(page, attendance_entries)
                else:
                    # STANDARD PAYROLL PAGE
                    # A. Header & Footer (Metadata)
                    # Define crop zones (approximate percentages based on A4)
                    width, height = page.width, page.height

                    # Top 20% for Header
                    header_crop = page.crop((0, 0, width, height * 0.20))
                    header_text = header_crop.extract_text()
                    if header_text:
                        cls._extract_key_values(header_text, metadata_accumulator)

                    # Bottom 20% for Footer (Totals, Leaves, Net)
                    footer_crop = page.crop((0, height * 0.80, width, height))
                    footer_text = footer_crop.extract_text()
                    if footer_text:
                        cls._extract_key_values(footer_text, metadata_accumulator)
                        # Also parse complex footer structures (Leaves, Fiscal) from text
                        cls._parse_footer_special(footer_text, extracted) 

                    # B. Middle Table (Payroll Rows)
                    # Crop middle section
                    middle_crop = page.crop((0, height * 0.20, width, height * 0.80))

                    # Strategy: Use explicit columns if possible, or text-based fallback
                    # Based on standard ITT layout, columns are roughly:
                    # Cod | Descrizione | Ore/GG | Dato Base | Competenze | Trattenute
                    # We'll use text extraction line-by-line which is safer for varying layouts than rigid explicit_vertical_lines unless we know them exactly.
                    middle_text = middle_crop.extract_text()
                    if middle_text:
                        cls._parse_payroll_text(middle_text, all_payroll_rows)

        # Map accumulated data to final structure
        cls._map_metadata(metadata_accumulator, extracted)
        extracted["items"] = all_payroll_rows
        extracted["attendance"] = attendance_entries

        return extracted

    @classmethod
    def _extract_key_values(cls, text: str, accumulator: Dict[str, Any]):
        """Parses standard Key: Value pairs from headers/footers."""
        # Employee Name
        name_match = re.search(r"Sig\.\s+([A-Z\s]+)\s+\d{4}", text)
        if name_match: accumulator["employee_name"] = name_match.group(1).strip()

        # Employee ID
        id_match = re.search(r"C\.I\.D\s.*?(\d{4})", text)
        if id_match: accumulator["employee_id"] = id_match.group(1)

        # Period
        period_match = re.search(r"([A-Z][a-z]+\s20\d{2})\s+Pagina", text)
        if period_match: accumulator["month_reference"] = period_match.group(1)

        # Net Pay
        net_match = re.search(r"Netto in busta\s+([\d\.]+,\d{2})", text)
        if net_match: accumulator["net_income"] = cls.parse_italian_float(net_match.group(1))

        # Contract Hours
        hours_match = re.search(r"Ore Contr\.\s+(\d+)", text)
        if hours_match: accumulator["contract_hours"] = float(hours_match.group(1))

        # Totals
        tot_header_match = re.search(r"Tot\.Comp\.\s+Tot\.Trat\.", text)
        if tot_header_match:
            # Look for the numbers in the same or next line
            # This regex looks for two currency values close to each other
            nums = re.findall(r"([\d\.]+,\d{2})", text[tot_header_match.end():])
            if len(nums) >= 2:
                accumulator["total_earnings"] = cls.parse_italian_float(nums[0])
                accumulator["total_deductions"] = cls.parse_italian_float(nums[1])

    @classmethod
    def _parse_payroll_text(cls, text: str, rows: List[Dict[str, Any]]):
        """Parses the middle section text into payroll rows."""
        lines = text.split('\n')
        parsing = False

        for line in lines:
            if "Cod. Descrizione" in line:
                parsing = True
                continue
            if not parsing:
                continue

            # Stop if we hit footer markers leaking into middle crop
            if "Tot.Comp." in line or "Netto in busta" in line:
                break

            line = line.strip()
            if not line: continue

            # Parse Row
            parts = line.split()
            if len(parts) > 1:
                # Heuristic parsing
                code = parts[0]

                # If code is not alphanumeric short code, skip (it's likely noise)
                if len(code) > 6: continue 

                # Reverse find numbers
                numbers = []
                desc_end_index = len(parts)

                for i in range(len(parts) - 1, 0, -1):
                    part = parts[i]
                    # Match Italian float or "X" placeholder
                    if re.match(r"^[\d\.]+,\d{2,4}-?$", part) or part == "X":
                         if part != "X":
                            numbers.insert(0, cls.parse_italian_float(part))
                         desc_end_index = i
                    else:
                        break

                description = " ".join(parts[1:desc_end_index])

                is_deduction = code.startswith("/") or "Tratt" in line or "Addiz" in line or code in ["076B", "0786"]

                item = {
                    "code": code,
                    "description": description,
                    "quantity": 0.0,
                    "base_data": 0.0,
                    "earnings": 0.0,
                    "deductions": 0.0,
                    "type": "Deduction" if is_deduction else "Earning"
                }

                # Assign values based on position/count
                # Standard Columns: Qty | Base | Earnings | Deductions
                # But typically only 3 numeric columns appear populated max per row
                if is_deduction:
                    if len(numbers) >= 1: item["deductions"] = numbers[-1]
                    if len(numbers) >= 2: item["base_data"] = numbers[-2]
                else:
                    if len(numbers) >= 1: item["earnings"] = numbers[-1]
                    if len(numbers) >= 2: item["base_data"] = numbers[-2]
                    if len(numbers) >= 3: item["quantity"] = numbers[-3]

                rows.append(item)

    @classmethod
    def _parse_footer_special(cls, text: str, extracted: Dict[str, Any]):
        """Parses Leaves and Fiscal Data from footer text."""
        # --- LEAVES ---
        cats = ["Ferie", "BancaOr", "ExFes/Rol", "Fless."]
        db_cat_map = {"Ferie": "Ferie", "BancaOr": "Banca Ore", "ExFes/Rol": "ROL/ExFest", "Fless.": "Flessibilita"}

        row_patterns = {
            "previous_residue": r"Res\.A\.P\.\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "accrued": r"Mat\.Anno\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "used": r"Goduto\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)",
            "remaining": r"Residuo\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)\s+([\d,\.-]+)"
        }

        # Only parse if we haven't already (or overwrite with latest page data which is usually cumulative)
        found_leaves = False
        for r_type, regex in row_patterns.items():
            match = re.search(regex, text)
            if match:
                found_leaves = True
                vals = match.groups()
                for i, cat in enumerate(cats):
                    if i < len(vals):
                        # Find existing leave entry or create new
                        mapped_cat = db_cat_map.get(cat, cat)
                        existing = next((l for l in extracted["leaves"] if l["leave_type"] == mapped_cat), None)
                        val_float = cls.parse_italian_float(vals[i])

                        if existing:
                            existing[r_type] = val_float
                        else:
                            new_leave = {"leave_type": mapped_cat, "previous_residue": 0, "accrued": 0, "used": 0, "remaining": 0}
                            new_leave[r_type] = val_float
                            extracted["leaves"].append(new_leave)

        # --- FISCAL ---
        if "Imp.Fisc" in text:
            fiscal = extracted["fiscal_data"]
            imp_fisc = re.search(r"Imp\.Fisc.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
            if imp_fisc: fiscal["taxable_income"] = cls.parse_italian_float(imp_fisc.group(1))

            imp_lord = re.search(r"Imposta L\.\s+(\d[\d\.]*,\d{2})", text)
            if imp_lord: fiscal["gross_tax"] = cls.parse_italian_float(imp_lord.group(1))

            imp_net = re.search(r"Imposta Net.*?(\d[\d\.]*,\d{2})", text, re.DOTALL)
            if imp_net: fiscal["net_tax"] = cls.parse_italian_float(imp_net.group(1))

            tfr_month = re.search(r"TFR Mese\s+([\d\.]*,\d{2})", text)
            if tfr_month: fiscal["tfr_month"] = cls.parse_italian_float(tfr_month.group(1))

    @classmethod
    def _extract_attendance_data(cls, page: Any, attendance_entries: List[Dict[str, Any]]):
        """Extracts attendance table using pdfplumber table extraction."""
        # Crop to skip header if known, or just extract table
        # We assume the table is the main content
        tables = page.extract_tables()

        for table in tables:
            # Check headers in first row
            if not table: continue

            # Normalize headers
            headers = [str(h).lower() for h in table[0] if h]
            if "data entrata" not in " ".join(headers):
                continue # Not the right table

            # Iterate data rows
            for row in table[1:]:
                # Expected: [Date, TimeIn, DateOut, TimeOut, ...]
                # Clean None values
                row = [r for r in row if r]
                if len(row) >= 2:
                    date_str = row[0]
                    time_in = row[1]
                    time_out = None

                    # Sometimes row is [Date, TimeIn, TimeOut] or [Date, TimeIn, Date, TimeOut]
                    # Logic: Try to parse date
                    try:
                        date_obj = datetime.datetime.strptime(date_str, "%d.%m.%Y").date()
                    except:
                        continue

                    if len(row) >= 4:
                         time_out = row[3] # Assuming [Date, TimeIn, DateOut, TimeOut]
                    elif len(row) == 3:
                         time_out = row[2] # Assuming [Date, TimeIn, TimeOut]

                    attendance_entries.append({
                        "date": date_obj,
                        "entry_time": time_in,
                        "exit_time": time_out
                    })

    @classmethod
    def _map_metadata(cls, metadata: Dict[str, Any], extracted: Dict[str, Any]):
        """Transfers metadata to the final extracted dict."""
        for key in ["employee_name", "employee_id", "month_reference", "net_income", "total_earnings", "total_deductions", "contract_hours"]:
            if key in metadata:
                extracted[key] = metadata[key]

        # Parse date from month ref
        if "month_reference" in metadata:
            try:
                months = {
                    "Gennaio": 1, "Febbraio": 2, "Marzo": 3, "Aprile": 4, "Maggio": 5, "Giugno": 6,
                    "Luglio": 7, "Agosto": 8, "Settembre": 9, "Ottobre": 10, "Novembre": 11, "Dicembre": 12
                }
                parts = metadata["month_reference"].split()
                if len(parts) == 2 and parts[0] in months:
                    extracted["date"] = datetime.date(int(parts[1]), months[parts[0]], 1)
            except:
                pass

elif doc_type == "salary":
    # Salary Parser (ITT only for now)
    data = ITTSalaryParser.parse(file_path)

    if dry_run:
         results.append({
            "filename": file.filename,
            "status": "preview",
            "parser_used": "itt_salary",
            "original_snippet": original_snippet,
            "parsed_preview": [data], # It's a single dict for salary
            "total_parsed": 1
        })
    else:
        # Relational storage
        items_data = data.pop("items")

