                    <p className={`font-bold ${tx.amount > 0 ? 'text-emerald-600' : 'text-txt-primary'}`}>{tx.amount > 0 ? '+' : ''}{tx.amount.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</p>
                    <p className="text-[10px] uppercase font-bold tracking-widest text-txt-secondary mt-1 opacity-60">{tx.category}</p>
                  </div>
                </div>
              )) : <div className="p-12 text-center text-txt-secondary italic">Ready for import.</div>}
            </div>
          </section>
        )}
      </main>

      {/* Upload Modal */}
      <UploadModal 
        isOpen={isUploadModalOpen} 
        onClose={() => setIsUploadModalOpen(false)} 
        onSuccess={() => fetchData()} 
        docType={uploadDocType} 
        apiBaseUrl={API_BASE_URL} 
      />

      {/* Parser Builder Modal */}
      {showParserBuilder && (
        <ParserBuilder 
            onClose={() => setShowParserBuilder(false)}
            apiBaseUrl={API_BASE_URL}
        />
      )}

      {/* Transaction Modal */}
      {showModal && editingTx && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-canvas w-full max-w-2xl rounded-[32px] shadow-2xl p-8 overflow-hidden">
            <div className="flex items-center justify-between mb-8">
               <h3 className="text-2xl font-bold">{editingTx.id ? 'Edit Transaction' : 'New Transaction'}</h3>
               <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition-colors"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveTx} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Date</label>
                  <input 
                    type="date" 
                    value={editingTx.date} 
                    onChange={e => setEditingTx({...editingTx, date: e.target.value})} 
                    className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                    required
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Amount</label>
                  <input 
                    type="number" 
                    step="0.01"
                    value={editingTx.amount} 
                    onChange={e => setEditingTx({...editingTx, amount: parseFloat(e.target.value)})} 
                    className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Operation / Description</label>
                <input 
                  type="text" 
                  value={editingTx.operation} 
                  onChange={e => setEditingTx({...editingTx, operation: e.target.value})} 
                  className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                  required
                />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Details (Optional)</label>
                <textarea 
                  value={editingTx.details} 
                  onChange={e => setEditingTx({...editingTx, details: e.target.value})} 
                  className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium h-24 resize-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Category</label>
                    <select 
                      value={editingTx.category} 
                      onChange={e => setEditingTx({...editingTx, category: e.target.value, subcategory: 'None', taxonomy_detail: ''})}
                      className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                    >
                      <option value="Uncategorized">Uncategorized</option>
                      {Object.keys(categories).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Subcategory</label>
                     <select 
                      value={editingTx.subcategory} 
                      onChange={e => setEditingTx({...editingTx, subcategory: e.target.value, taxonomy_detail: ''})}
                      className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                    >
                      <option value="None">None</option>
                      {categories[editingTx.category] && Object.keys(categories[editingTx.category]).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                 </div>
              </div>

              {editingTx.subcategory !== 'None' && categories[editingTx.category]?.[editingTx.subcategory] && (
                  <div className="space-y-2">
                    <label className="text-xs font-bold uppercase text-txt-secondary tracking-wider">Detail</label>
                    <select 
                        value={editingTx.taxonomy_detail} 
                        onChange={e => setEditingTx({...editingTx, taxonomy_detail: e.target.value})}
                        className="w-full bg-surface p-3 rounded-xl border-2 border-slate-100 focus:border-primary-start outline-none font-medium"
                    >
                        <option value="">Select Detail...</option>
                        {(() => {
                            const detailData = categories[editingTx.category][editingTx.subcategory];
                            if (Array.isArray(detailData)) {
                                return detailData.map((d: string) => <option key={d} value={d}>{d}</option>);
                            } else if (typeof detailData === 'object') {
                                return Object.keys(detailData).map((d: string) => <option key={d} value={d}>{d}</option>);
                            }
                            return null;
                        })()}
                    </select>
                  </div>
              )}

              <div className="pt-4 flex justify-end gap-4">
                <button type="button" onClick={() => setShowModal(false)} className="px-6 py-3 font-bold text-txt-secondary hover:bg-slate-50 rounded-xl transition-colors">Cancel</button>
                <button type="submit" className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white font-bold rounded-xl shadow-lg hover:scale-105 transition-transform">
                  <Save size={18} /> Save Transaction
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Duplicate Manager Modal */}
      {showDuplicatesModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-canvas w-full max-w-4xl max-h-[85vh] rounded-[40px] shadow-2xl p-10 overflow-hidden flex flex-col">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-3xl font-black tracking-tighter">Duplicate Manager</h3>
                <p className="text-txt-secondary font-medium">Review and resolve identical transaction records.</p>
              </div>
              <button onClick={() => setShowDuplicatesModal(false)} className="p-3 bg-surface hover:bg-slate-100 rounded-2xl transition-colors"><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-8">
              {duplicateGroups.map((group, gIdx) => (
                <div key={gIdx} className="bg-surface rounded-3xl border border-slate-100 shadow-soft overflow-hidden">
                  <div className="bg-slate-50/50 px-8 py-4 border-b border-slate-100 flex justify-between items-center">
                    <div className="flex gap-6 items-center">
                      <span className="text-sm font-black text-slate-400">GROUP #{gIdx + 1}</span>
                      <span className="text-sm font-bold text-txt-primary">{group.info.operation}</span>
                      <span className="text-sm font-black text-primary-end font-mono">€{group.info.amount.toLocaleString()}</span>
                    </div>
                    <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">{group.records.length} Conflicts</span>
                  </div>
                  <div className="p-2">
                    <table className="w-full text-left">
                      <thead>
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                          <th className="px-6 py-3">Database ID</th>
                          <th className="px-6 py-3">Import Date</th>
                          <th className="px-6 py-3">Source</th>
                          <th className="px-6 py-3 text-right">Action</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {group.records.map((rec: any) => (
                          <tr key={rec.id} className="group hover:bg-slate-50/50 transition-colors">
                            <td className="px-6 py-4 font-mono text-xs font-bold text-slate-400">#{rec.id}</td>
                            <td className="px-6 py-4 text-xs font-bold">{new Date(rec.created_at).toLocaleString()}</td>
                            <td className="px-6 py-4">
                              <span className="bg-canvas px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-tighter border border-slate-100">{rec.source_bank}</span>
                            </td>
                            <td className="px-6 py-4 text-right">
                              <button 
                                onClick={async () => {
                                  await axios.delete(`${API_BASE_URL}/api/transactions/${rec.id}`);
                                  // Update local state to remove the item
                                  const newGroups = [...duplicateGroups];
                                  newGroups[gIdx].records = newGroups[gIdx].records.filter((r: any) => r.id !== rec.id);
                                  if (newGroups[gIdx].records.length <= 1) {
                                    newGroups.splice(gIdx, 1);
                                  }
                                  setDuplicateGroups(newGroups);
                                  if (newGroups.length === 0) setShowDuplicatesModal(false);
                                  fetchData();
                                }}
                                className="p-2 text-rose-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                              >
                                <Trash2 size={16} />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-8 pt-8 border-t border-slate-100 flex justify-end gap-4">
              <button onClick={() => setShowDuplicatesModal(false)} className="px-8 py-4 bg-slate-900 text-white font-black rounded-2xl shadow-xl transition-transform hover:scale-105">Done Reviewing</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { X, Save, Play, Plus, Trash2, Settings, FileText, Table as TableIcon, AlignLeft } from 'lucide-react';

interface ParserBuilderProps {
  onClose: () => void;
  apiBaseUrl: string;
}

type ColumnType = 'string' | 'currency' | 'float' | 'date';

interface ColumnDef {
  x: number;
  name: string;
  type: ColumnType;
}

export const ParserBuilder: React.FC<ParserBuilderProps> = ({ onClose, apiBaseUrl }) => {
  // Layout State
  const [zones, setZones] = useState({
    header: 30,
    middle: 30,
    footer: 40
  });

  // Logic/Strategy State
  const [pageStrategy, setPageStrategy] = useState({
    mode: 'all', // 'all', 'regex', 'first', 'last'
    regex: '',
    stopCondition: '' // e.g. "Netto in busta"
  });

  const [middleZoneConfig, setMiddleZoneConfig] = useState({
    type: 'table', // 'text', 'table', 'kv'
    columns: [
        { x: 50, name: 'Code', type: 'string' },
        { x: 270, name: 'Description', type: 'string' },
        { x: 300, name: 'Flags', type: 'string' },
        { x: 340, name: 'Quantity', type: 'float' },
        { x: 410, name: 'Base', type: 'float' },
        { x: 490, name: 'Earnings', type: 'currency' }
    ] as ColumnDef[]
  });

  const updateColumn = (idx: number, field: keyof ColumnDef, value: any) => {
    const newCols = [...middleZoneConfig.columns];
    newCols[idx] = { ...newCols[idx], [field]: value };
    setMiddleZoneConfig({ ...middleZoneConfig, columns: newCols });
  };

  const removeColumn = (idx: number) => {
    setMiddleZoneConfig({ 
        ...middleZoneConfig, 
        columns: middleZoneConfig.columns.filter((_, i) => i !== idx) 
    });
  };

  const addColumn = () => {
    const lastX = middleZoneConfig.columns.length > 0 
        ? middleZoneConfig.columns[middleZoneConfig.columns.length - 1].x 
        : 0;
    setMiddleZoneConfig({
        ...middleZoneConfig,
        columns: [...middleZoneConfig.columns, { x: lastX + 50, name: 'New Col', type: 'string' }]
    });
  };

  return (
    <div className="fixed inset-0 bg-canvas z-50 overflow-y-auto">
      <div className="max-w-7xl mx-auto p-8">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Parser Template Builder</h1>
            <p className="text-txt-secondary">Map document layouts and define extraction logic.</p>
          </div>
          <div className="flex gap-4">
            <button className="flex items-center gap-2 px-6 py-2 bg-slate-900 text-white rounded-xl font-bold hover:scale-105 transition-transform">
              <Save size={18} /> Save Template
            </button>
            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full">
              <X size={24} />
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Controls Sidebar */}
          <div className="lg:col-span-1 space-y-6">

            {/* 1. Page Strategy */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
                <h3 className="font-bold mb-4 flex items-center gap-2"><Settings size={16} /> Page Strategy</h3>
                <div className="space-y-3">
                    <div>
                        <label className="text-xs font-bold uppercase text-txt-secondary">Identify Pages By</label>
                        <select 
                            value={pageStrategy.mode} 
                            onChange={(e) => setPageStrategy({...pageStrategy, mode: e.target.value})}
                            className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-medium"
                        >
                            <option value="all">All Pages (Standard)</option>
                            <option value="regex">Text Match (Regex)</option>
                            <option value="first">First Page Only</option>
                        </select>
                    </div>
                    {pageStrategy.mode === 'regex' && (
                        <div>
                            <label className="text-xs font-bold uppercase text-txt-secondary">Regex Pattern</label>
                            <input 
                                type="text" 
                                placeholder="e.g. Data entrata.*" 
                                value={pageStrategy.regex}
                                onChange={(e) => setPageStrategy({...pageStrategy, regex: e.target.value})}
                                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-mono"
                            />
                        </div>
                    )}
                    <div>
                        <label className="text-xs font-bold uppercase text-txt-secondary">Stop Condition (Text)</label>
                        <input 
                            type="text" 
                            placeholder="e.g. Totale Netto" 
                            value={pageStrategy.stopCondition}
                            onChange={(e) => setPageStrategy({...pageStrategy, stopCondition: e.target.value})}
                            className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm"
                        />
                        <p className="text-[10px] text-slate-400 mt-1">Parser will stop adding rows if this text is found.</p>
                    </div>
                </div>
            </div>

            {/* 2. Zone Layout */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
              <h3 className="font-bold mb-4 flex items-center gap-2"><AlignLeft size={16} /> Layout Zones</h3>
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Header Height</label>
                  <input type="range" min="0" max="50" value={zones.header} onChange={e => setZones({...zones, header: parseInt(e.target.value)})} className="w-full accent-rose-500" />
                  <div className="text-right text-xs font-mono text-rose-500">{zones.header}%</div>
                </div>
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Middle Height</label>
                  <input type="range" min="10" max="100" value={zones.middle} onChange={e => setZones({...zones, middle: parseInt(e.target.value)})} className="w-full accent-emerald-500" />
                  <div className="text-right text-xs font-mono text-emerald-600">{zones.middle}%</div>
                </div>
              </div>
            </div>

            {/* 3. Extraction Logic (Middle Zone) */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
              <h3 className="font-bold mb-4 flex items-center gap-2"><TableIcon size={16} /> Extraction Logic</h3>

              <div className="flex gap-2 mb-4 p-1 bg-slate-50 rounded-xl">
                <button 
                    onClick={() => setMiddleZoneConfig({...middleZoneConfig, type: 'table'})}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${middleZoneConfig.type === 'table' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Table
                </button>
                <button 
                    onClick={() => setMiddleZoneConfig({...middleZoneConfig, type: 'text'})}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${middleZoneConfig.type === 'text' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Raw Text
                </button>
              </div>

              {middleZoneConfig.type === 'table' ? (
                  <div className="space-y-2">
                    <div className="grid grid-cols-12 gap-2 text-[10px] font-bold uppercase text-slate-400 mb-1">
                        <span className="col-span-2">X-Pos</span>
                        <span className="col-span-5">Name</span>
                        <span className="col-span-4">Type</span>
                        <span className="col-span-1"></span>
                    </div>
                    <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
                        {middleZoneConfig.columns.map((col, idx) => (
                        <div key={idx} className="grid grid-cols-12 gap-2 items-center">
                            <input 
                                type="number" 
                                value={col.x} 
                                onChange={(e) => updateColumn(idx, 'x', parseInt(e.target.value))}
                                className="col-span-2 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-xs font-mono"
                            />
                            <input 
                                type="text" 
                                value={col.name} 
                                onChange={(e) => updateColumn(idx, 'name', e.target.value)}
                                className="col-span-5 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-xs font-bold"
                            />
                            <select
                                value={col.type}
                                onChange={(e) => updateColumn(idx, 'type', e.target.value)}
                                className="col-span-4 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-[10px]"
                            >
                                <option value="string">String</option>
                                <option value="currency">Currency</option>
                                <option value="float">Float</option>
                                <option value="date">Date</option>
                            </select>
                            <button onClick={() => removeColumn(idx)} className="col-span-1 text-rose-300 hover:text-rose-500"><Trash2 size={12} /></button>
                        </div>
                        ))}
                    </div>
                    <button 
                        onClick={addColumn}
                        className="w-full mt-2 py-2 border border-dashed border-emerald-200 text-emerald-600 rounded-xl text-xs font-bold hover:bg-emerald-50 transition-colors flex items-center justify-center gap-1"
                    >
                        <Plus size={12} /> Add Column
                    </button>
                  </div>
              ) : (
                  <div className="p-4 bg-blue-50 rounded-xl text-xs text-blue-700">
                      <p className="font-bold mb-1">Raw Text Mode</p>
                      <p>Content in the middle zone will be extracted as a single text block. Useful for descriptions or notes.</p>
                  </div>
              )}
            </div>

            <button className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-colors shadow-lg">
                <Play size={18} /> Test Extraction
            </button>
          </div>

          {/* Visual Editor (Canvas) */}
          <div className="lg:col-span-2 bg-slate-200 rounded-[32px] min-h-[700px] flex items-center justify-center border-4 border-dashed border-slate-300 relative overflow-hidden p-8">
             {/* Simulated PDF Page */}
             <div className="bg-white w-[595px] h-[842px] shadow-2xl relative transition-all">

                {/* Header Zone */}
                <div 
                    className="absolute left-0 w-full bg-rose-500/10 border-b-2 border-rose-500/50 flex flex-col items-center justify-center text-rose-700 font-bold uppercase tracking-widest text-xs group hover:bg-rose-500/20 transition-colors cursor-ns-resize"
                    style={{ top: 0, height: `${zones.header}%` }}
                >
                    <span className="bg-white/80 px-2 py-1 rounded shadow-sm backdrop-blur-sm">Header (Metadata)</span>
                </div>

                {/* Middle Zone */}
                <div 
                    className="absolute left-0 w-full bg-emerald-500/10 border-b-2 border-emerald-500/50 flex items-center justify-center text-emerald-700 font-bold uppercase tracking-widest text-xs group hover:bg-emerald-500/20 transition-colors"
                    style={{ top: `${zones.header}%`, height: `${zones.middle}%` }}
                >
                    <span className="absolute top-2 left-2 bg-white/80 px-2 py-1 rounded shadow-sm text-[10px] backdrop-blur-sm text-emerald-800">
                        Middle ({middleZoneConfig.type === 'table' ? 'Structured Table' : 'Raw Text'})
                    </span>

                    {/* Column Lines */}
                    {middleZoneConfig.type === 'table' && middleZoneConfig.columns.map((col, i) => (
                        <div 
                            key={i} 
                            className="absolute top-0 bottom-0 border-l-2 border-purple-500/60 group hover:border-purple-600"
                            style={{ left: `${col.x}px` }}
                        >
                            <div className="absolute -top-3 -left-px bg-purple-600 text-white text-[9px] px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap z-10">
                                {col.name} <span className="opacity-70">({col.type})</span>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Footer Zone */}
                <div 
                    className="absolute left-0 w-full bg-blue-500/10 border-t-2 border-blue-500/50 flex items-center justify-center text-blue-700 font-bold uppercase tracking-widest text-xs group hover:bg-blue-500/20 transition-colors"
                    style={{ top: `${zones.header + zones.middle}%`, bottom: 0 }}
                >
                    <span className="bg-white/80 px-2 py-1 rounded shadow-sm backdrop-blur-sm">Footer (Totals & Fiscal)</span>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

