              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Header Height (%)</label>
                  <input type="range" min="0" max="100" value={zones.header} onChange={e => setZones({...zones, header: parseInt(e.target.value)})} className="w-full accent-primary-start" />
                  <div className="flex justify-between text-xs font-mono"><span>0%</span><span>{zones.header}%</span></div>
                </div>
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Middle Height (%)</label>
                  <input type="range" min="0" max="100" value={zones.middle} onChange={e => setZones({...zones, middle: parseInt(e.target.value)})} className="w-full accent-emerald-500" />
                  <div className="flex justify-between text-xs font-mono"><span>0%</span><span>{zones.middle}%</span></div>
                </div>
              </div>
            </div>

            <div className="bg-surface p-6 rounded-2xl shadow-soft">
              <h3 className="font-bold mb-4">Columns (Horizontal Split)</h3>
              <p className="text-xs text-txt-secondary mb-4">Define X-coordinates for column separators in the middle zone.</p>

              <div className="space-y-2 max-h-60 overflow-y-auto">
                {columns.map((col, idx) => (
                  <div key={idx} className="flex items-center gap-2">
                    <span className="text-xs font-mono font-bold w-6">#{idx+1}</span>
                    <input 
                      type="number" 
                      value={col} 
                      onChange={(e) => {
                        const newCols = [...columns];
                        newCols[idx] = parseInt(e.target.value);
                        setColumns(newCols);
                      }}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-sm font-mono"
                    />
                    <button onClick={() => setColumns(columns.filter((_, i) => i !== idx))} className="text-rose-400 hover:text-rose-600"><Trash2 size={14} /></button>
                  </div>
                ))}
              </div>
              <button 
                onClick={() => setColumns([...columns, 0])}
                className="w-full mt-4 flex items-center justify-center gap-2 py-2 border-2 border-dashed border-slate-200 rounded-xl text-xs font-bold text-slate-400 hover:border-primary-start hover:text-primary-start transition-colors"
              >
                <Plus size={14} /> Add Separator
              </button>
            </div>

            <button className="w-full py-4 bg-primary-start/10 text-primary-start font-bold rounded-2xl flex items-center justify-center gap-2 hover:bg-primary-start/20 transition-colors">
                <Play size={18} /> Test Extraction
            </button>
          </div>

          {/* Visual Editor (Placeholder) */}
          <div className="col-span-2 bg-slate-200 rounded-3xl min-h-[600px] flex items-center justify-center border-4 border-dashed border-slate-300 relative overflow-hidden">
             {/* Simulated PDF Page */}
             <div className="bg-white w-[595px] h-[842px] shadow-2xl relative">
                {/* Zone Overlays */}
                <div 
                    className="absolute left-0 w-full bg-rose-500/20 border-b-2 border-rose-500 flex items-center justify-center text-rose-700 font-bold uppercase tracking-widest text-sm"
                    style={{ top: 0, height: `${zones.header}%` }}
                >
                    Header Zone
                </div>
                <div 
                    className="absolute left-0 w-full bg-emerald-500/20 border-b-2 border-emerald-500 flex items-center justify-center text-emerald-700 font-bold uppercase tracking-widest text-sm"
                    style={{ top: `${zones.header}%`, height: `${zones.middle}%` }}
                >
                    {/* Column Lines */}
                    {columns.map((x, i) => (
                        <div 
                            key={i} 
                            className="absolute top-0 bottom-0 border-l-2 border-purple-500/50"
                            style={{ left: `${x}px` }}
                        >
                            <span className="absolute top-0 -left-3 bg-purple-500 text-white text-[9px] px-1 rounded">{x}</span>
                        </div>
                    ))}
                    Middle (Table) Zone
                </div>
                <div 
                    className="absolute left-0 w-full bg-blue-500/20 border-t-2 border-blue-500 flex items-center justify-center text-blue-700 font-bold uppercase tracking-widest text-sm"
                    style={{ top: `${zones.header + zones.middle}%`, bottom: 0 }}
                >
                    Footer Zone
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

