  const [testFile, setTestFile] = useState<File | null>(null);
  const [previewData, setPreviewData] = useState<any[]>([]);
  const [debugImage, setDebugImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleTestExtraction = async () => {
    if (!testFile) {
        alert("Please upload a sample file first.");
        return;
    }

    setIsLoading(true);
    const formData = new FormData();
    formData.append('file', testFile);
    formData.append('config', JSON.stringify({
        zones,
        columns: middleZoneConfig.columns
    }));

    try {
        const res = await axios.post(`${apiBaseUrl}/api/parsers/preview`, formData);
        setPreviewData(res.data.extracted_data);
        setDebugImage(res.data.debug_image);
    } catch (error) {
        alert("Extraction failed");
    } finally {
        setIsLoading(false);
    }
  };

  const updateColumn = (idx: number, field: keyof ColumnDef, value: any) => {
    const newCols = [...middleZoneConfig.columns];
    newCols[idx] = { ...newCols[idx], [field]: value };
    setMiddleZoneConfig({ ...middleZoneConfig, columns: newCols });
  };

  const removeColumn = (idx: number) => {
    setMiddleZoneConfig({ 
        ...middleZoneConfig, 
        columns: middleZoneConfig.columns.filter((_, i) => i !== idx) 
    });
  };

  const addColumn = () => {
    const lastX = middleZoneConfig.columns.length > 0 
        ? middleZoneConfig.columns[middleZoneConfig.columns.length - 1].x 
        : 0;
    setMiddleZoneConfig({
        ...middleZoneConfig,
        columns: [...middleZoneConfig.columns, { x: lastX + 50, name: 'New Col', type: 'string' }]
    });
  };

  return (
    <div className="fixed inset-0 bg-canvas z-50 overflow-y-auto">
      <div className="max-w-7xl mx-auto p-8">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Parser Template Builder</h1>
            <p className="text-txt-secondary">Map document layouts and define extraction logic.</p>
          </div>
          <div className="flex gap-4">
            <button className="flex items-center gap-2 px-6 py-2 bg-slate-900 text-white rounded-xl font-bold hover:scale-105 transition-transform">
              <Save size={18} /> Save Template
            </button>
            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full">
              <X size={24} />
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Controls Sidebar */}
          <div className="lg:col-span-1 space-y-6">

            {/* 0. File Upload */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
                <h3 className="font-bold mb-4 flex items-center gap-2"><FileText size={16} /> Sample Document</h3>
                <input 
                    type="file" 
                    onChange={(e) => setTestFile(e.target.files ? e.target.files[0] : null)}
                    className="w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-slate-100 file:text-slate-700 hover:file:bg-slate-200"
                />
                {testFile && <p className="text-xs text-emerald-600 mt-2 font-bold">Loaded: {testFile.name}</p>}
            </div>

            {/* 1. Page Strategy */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
                <h3 className="font-bold mb-4 flex items-center gap-2"><Settings size={16} /> Page Strategy</h3>
                <div className="space-y-3">
                    <div>
                        <label className="text-xs font-bold uppercase text-txt-secondary">Identify Pages By</label>
                        <select 
                            value={pageStrategy.mode} 
                            onChange={(e) => setPageStrategy({...pageStrategy, mode: e.target.value})}
                            className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-medium"
                        >
                            <option value="all">All Pages (Standard)</option>
                            <option value="regex">Text Match (Regex)</option>
                            <option value="first">First Page Only</option>
                        </select>
                    </div>
                    {pageStrategy.mode === 'regex' && (
                        <div>
                            <label className="text-xs font-bold uppercase text-txt-secondary">Regex Pattern</label>
                            <input 
                                type="text" 
                                placeholder="e.g. Data entrata.*" 
                                value={pageStrategy.regex}
                                onChange={(e) => setPageStrategy({...pageStrategy, regex: e.target.value})}
                                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-mono"
                            />
                        </div>
                    )}
                    <div>
                        <label className="text-xs font-bold uppercase text-txt-secondary">Stop Condition (Text)</label>
                        <input 
                            type="text" 
                            placeholder="e.g. Totale Netto" 
                            value={pageStrategy.stopCondition}
                            onChange={(e) => setPageStrategy({...pageStrategy, stopCondition: e.target.value})}
                            className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm"
                        />
                        <p className="text-[10px] text-slate-400 mt-1">Parser will stop adding rows if this text is found.</p>
                    </div>
                </div>
            </div>

            {/* 2. Zone Layout */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
              <h3 className="font-bold mb-4 flex items-center gap-2"><AlignLeft size={16} /> Layout Zones</h3>
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Header Height</label>
                  <input type="range" min="0" max="50" value={zones.header} onChange={e => setZones({...zones, header: parseInt(e.target.value)})} className="w-full accent-rose-500" />
                  <div className="text-right text-xs font-mono text-rose-500">{zones.header}%</div>
                </div>
                <div>
                  <label className="text-xs font-bold uppercase text-txt-secondary">Middle Height</label>
                  <input type="range" min="10" max="100" value={zones.middle} onChange={e => setZones({...zones, middle: parseInt(e.target.value)})} className="w-full accent-emerald-500" />
                  <div className="text-right text-xs font-mono text-emerald-600">{zones.middle}%</div>
                </div>
              </div>
            </div>

            {/* 3. Extraction Logic (Middle Zone) */}
            <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
              <h3 className="font-bold mb-4 flex items-center gap-2"><TableIcon size={16} /> Extraction Logic</h3>

              <div className="flex gap-2 mb-4 p-1 bg-slate-50 rounded-xl">
                <button 
                    onClick={() => setMiddleZoneConfig({...middleZoneConfig, type: 'table'})}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${middleZoneConfig.type === 'table' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Table
                </button>
                <button 
                    onClick={() => setMiddleZoneConfig({...middleZoneConfig, type: 'text'})}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${middleZoneConfig.type === 'text' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Raw Text
                </button>
              </div>

              {middleZoneConfig.type === 'table' ? (
                  <div className="space-y-2">
                    <div className="grid grid-cols-12 gap-2 text-[10px] font-bold uppercase text-slate-400 mb-1">
                        <span className="col-span-2">X-Pos</span>
                        <span className="col-span-5">Name</span>
                        <span className="col-span-4">Type</span>
                        <span className="col-span-1"></span>
                    </div>
                    <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
                        {middleZoneConfig.columns.map((col, idx) => (
                        <div key={idx} className="grid grid-cols-12 gap-2 items-center">
                            <input 
                                type="number" 
                                value={col.x} 
                                onChange={(e) => updateColumn(idx, 'x', parseInt(e.target.value))}
                                className="col-span-2 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-xs font-mono"
                            />
                            <input 
                                type="text" 
                                value={col.name} 
                                onChange={(e) => updateColumn(idx, 'name', e.target.value)}
                                className="col-span-5 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-xs font-bold"
                            />
                            <select
                                value={col.type}
                                onChange={(e) => updateColumn(idx, 'type', e.target.value)}
                                className="col-span-4 bg-slate-50 border border-slate-200 rounded px-1 py-1 text-[10px]"
                            >
                                <option value="string">String</option>
                                <option value="currency">Currency</option>
                                <option value="float">Float</option>
                                <option value="date">Date</option>
                            </select>
                            <button onClick={() => removeColumn(idx)} className="col-span-1 text-rose-300 hover:text-rose-500"><Trash2 size={12} /></button>
                        </div>
                        ))}
                    </div>
                    <button 
                        onClick={addColumn}
                        className="w-full mt-2 py-2 border border-dashed border-emerald-200 text-emerald-600 rounded-xl text-xs font-bold hover:bg-emerald-50 transition-colors flex items-center justify-center gap-1"
                    >
                        <Plus size={12} /> Add Column
                    </button>
                  </div>
              ) : (
                  <div className="p-4 bg-blue-50 rounded-xl text-xs text-blue-700">
                      <p className="font-bold mb-1">Raw Text Mode</p>
                      <p>Content in the middle zone will be extracted as a single text block. Useful for descriptions or notes.</p>
                  </div>
              )}
            </div>

            <button 
                onClick={handleTestExtraction}
                disabled={!testFile || isLoading}
                className={`w-full py-4 font-bold rounded-2xl flex items-center justify-center gap-2 shadow-lg transition-all ${!testFile ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800'}`}
            >
                {isLoading ? <span className="animate-spin">⟳</span> : <Play size={18} />} Test Extraction
            </button>

            {/* Results Preview */}
            {previewData.length > 0 && (
                <div className="bg-white border border-slate-200 rounded-2xl p-4 shadow-soft max-h-64 overflow-y-auto">
                    <h4 className="text-xs font-bold uppercase text-slate-400 mb-2">Extraction Results ({previewData.length} rows)</h4>
                    <pre className="text-[10px] font-mono whitespace-pre-wrap">
                        {JSON.stringify(previewData, null, 2)}
                    </pre>
                </div>
            )}
          </div>

          {/* Visual Editor (Canvas) */}
          <div className="lg:col-span-2 bg-slate-200 rounded-[32px] min-h-[700px] flex items-center justify-center border-4 border-dashed border-slate-300 relative overflow-hidden p-8">
             {/* PDF Page Container */}
             <div className="bg-white w-[595px] h-[842px] shadow-2xl relative transition-all">

                {/* Debug Image Overlay */}
                {debugImage && (
                    <img 
                        src={`data:image/png;base64,${debugImage}`} 
                        alt="Debug Preview" 
                        className="absolute inset-0 w-full h-full object-contain opacity-50 pointer-events-none" 
                    />
                )}

                {/* Header Zone */}
                <div 
                    className="absolute left-0 w-full bg-rose-500/10 border-b-2 border-rose-500/50 flex flex-col items-center justify-center text-rose-700 font-bold uppercase tracking-widest text-xs group hover:bg-rose-500/20 transition-colors cursor-ns-resize"
                    style={{ top: 0, height: `${zones.header}%` }}
                >
                    <span className="bg-white/80 px-2 py-1 rounded shadow-sm backdrop-blur-sm">Header (Metadata)</span>
                </div>

                {/* Middle Zone */}
                <div 
                    className="absolute left-0 w-full bg-emerald-500/10 border-b-2 border-emerald-500/50 flex items-center justify-center text-emerald-700 font-bold uppercase tracking-widest text-xs group hover:bg-emerald-500/20 transition-colors"
                    style={{ top: `${zones.header}%`, height: `${zones.middle}%` }}
                >
                    {!debugImage && (
                        <span className="absolute top-2 left-2 bg-white/80 px-2 py-1 rounded shadow-sm text-[10px] backdrop-blur-sm text-emerald-800">
                            Middle ({middleZoneConfig.type === 'table' ? 'Structured Table' : 'Raw Text'})
                        </span>
                    )}

                    {/* Column Lines */}
                    {middleZoneConfig.type === 'table' && middleZoneConfig.columns.map((col, i) => (
                        <div 
                            key={i} 
                            className="absolute top-0 bottom-0 border-l-2 border-purple-500/60 group hover:border-purple-600"
                            style={{ left: `${col.x}px` }}
                        >
                            <div className="absolute -top-3 -left-px bg-purple-600 text-white text-[9px] px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap z-10">
                                {col.name} <span className="opacity-70">({col.type})</span>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Footer Zone */}
                <div 
                    className="absolute left-0 w-full bg-blue-500/10 border-t-2 border-blue-500/50 flex items-center justify-center text-blue-700 font-bold uppercase tracking-widest text-xs group hover:bg-blue-500/20 transition-colors"
                    style={{ top: `${zones.header + zones.middle}%`, bottom: 0 }}
                >
                    <span className="bg-white/80 px-2 py-1 rounded shadow-sm backdrop-blur-sm">Footer (Totals & Fiscal)</span>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

