import React, { useState, useRef, useEffect } from 'react';
import { X, Save, Play, Plus, Trash2, Settings, FileText, Table as TableIcon, AlignLeft, ChevronLeft, ChevronRight, MousePointer2, List as ListIcon, Edit } from 'lucide-react';
import axios from 'axios';

interface ParserBuilderProps {
  onClose: () => void;
  apiBaseUrl: string;
}

type RegionType = 'table' | 'text' | 'key_value';
type ColumnType = 'string' | 'currency' | 'float' | 'date';

interface ColumnDef {
  x: number; 
  name: string;
  type: ColumnType;
}

interface Region {
  id: string;
  x: number; // %
  y: number; // %
  w: number; // %
  h: number; // %
  type: RegionType;
  name: string;
  columns?: ColumnDef[];
}

export const ParserBuilder: React.FC<ParserBuilderProps> = ({ onClose, apiBaseUrl }) => {
  // View State
  const [view, setView] = useState<'list' | 'edit'>('list');
  const [templates, setTemplates] = useState<any[]>([]);

  // Template State
  const [templateId, setTemplateId] = useState<string | null>(null);
  const [templateName, setTemplateName] = useState('');

  // Builder State
  const [regions, setRegions] = useState<Region[]>([]);
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);
  const [pageStrategy, setPageStrategy] = useState({
    mode: 'all',
    regex: '',
    stopCondition: ''
  });

  // Page Navigation
  const [currentPage, setCurrentPage] = useState(0);
  const [pageCount, setPageCount] = useState(1);

  // Data Preview
  const [testFile, setTestFile] = useState<File | null>(null);
  const [previewData, setPreviewData] = useState<any>({});
  const [debugImage, setDebugImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Drawing State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState({ x: 0, y: 0, w: 0, h: 0 });

  // -------------------------------------------------------------------------
  // Template Management
  // -------------------------------------------------------------------------
  useEffect(() => {
      fetchTemplates();
  }, []);

  const fetchTemplates = async () => {
      try {
          const res = await axios.get(`${apiBaseUrl}/api/parsers/templates`);
          setTemplates(res.data);
      } catch (err) {
          console.error("Failed to load templates");
      }
  };

  const handleSaveTemplate = async () => {
      if (!templateName.trim()) {
          alert("Please name your template.");
          return;
      }

      try {
          const payload = {
              id: templateId,
              name: templateName,
              page_strategy: pageStrategy,
              regions: regions
          };

          await axios.post(`${apiBaseUrl}/api/parsers/templates`, payload);
          alert("Template saved!");
          fetchTemplates();
          setView('list');
      } catch (error) {
          alert("Failed to save template.");
      }
  };

  const handleEditTemplate = (tmpl: any) => {
      setTemplateId(tmpl.id);
      setTemplateName(tmpl.name);
      setPageStrategy(tmpl.page_strategy || { mode: 'all', regex: '', stopCondition: '' });
      setRegions(tmpl.regions || []);

      // Reset preview state
      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setCurrentPage(0);

      setView('edit');
  };

  const handleDeleteTemplate = async (id: string) => {
      if (!window.confirm("Are you sure?")) return;
      try {
          await axios.delete(`${apiBaseUrl}/api/parsers/templates/${id}`);
          fetchTemplates();
      } catch (err) {
          alert("Delete failed.");
      }
  };

  const handleNewTemplate = () => {
      setTemplateId(null);
      setTemplateName("New Template");
      setRegions([]);
      setPageStrategy({ mode: 'all', regex: '', stopCondition: '' });
      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setView('edit');
  };

  // -------------------------------------------------------------------------
  // drawing Logic
  // -------------------------------------------------------------------------
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!canvasRef.current) return;
    if ((e.target as HTMLElement).closest('.region-box')) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsDrawing(true);
    setStartPos({ x, y });
    setCurrentRect({ x, y, w: 0, h: 0 });
    setSelectedRegionId(null); 
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const currentX = e.clientX - rect.left;
    const currentY = e.clientY - rect.top;

    const width = currentX - startPos.x;
    const height = currentY - startPos.y;

    setCurrentRect({
        x: width > 0 ? startPos.x : currentX,
        y: height > 0 ? startPos.y : currentY,
        w: Math.abs(width),
        h: Math.abs(height)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !canvasRef.current) return;
    setIsDrawing(false);

    if (currentRect.w < 10 || currentRect.h < 10) return;

    const containerW = canvasRef.current.offsetWidth;
    const containerH = canvasRef.current.offsetHeight;

    const newRegion: Region = {
        id: Math.random().toString(36).substr(2, 9),
        x: (currentRect.x / containerW) * 100,
        y: (currentRect.y / containerH) * 100,
        w: (currentRect.w / containerW) * 100,
        h: (currentRect.h / containerH) * 100,
        type: 'text',
        name: `Region ${regions.length + 1}`,
        columns: []
    };

    setRegions([...regions, newRegion]);
    setSelectedRegionId(newRegion.id);
    setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
  };

  // -------------------------------------------------------------------------
  // API Actions
  // -------------------------------------------------------------------------
  const handleTestExtraction = async () => {
    if (!testFile) {
        alert("Please upload a sample file first.");
        return;
    }

    setIsLoading(true);
    const formData = new FormData();
    formData.append('file', testFile);
    formData.append('page', currentPage.toString());
    formData.append('config', JSON.stringify({
        regions
    }));

    try {
        const res = await axios.post(`${apiBaseUrl}/api/parsers/preview`, formData);
        setPreviewData(res.data.extracted_data);
        setDebugImage(res.data.debug_image);
        if (res.data.page_count) setPageCount(res.data.page_count);
    } catch (error) {
        alert("Extraction failed");
    } finally {
        setIsLoading(false);
    }
  };

  useEffect(() => {
      if (testFile && regions.length > 0) {
          handleTestExtraction();
      }
  }, [currentPage]);


  // -------------------------------------------------------------------------
  // Region Editing Logic
  // -------------------------------------------------------------------------
  const selectedRegion = regions.find(r => r.id === selectedRegionId);

  const updateRegion = (field: keyof Region, value: any) => {
      if (!selectedRegion) return;
      const updated = regions.map(r => r.id === selectedRegionId ? { ...r, [field]: value } : r);
      setRegions(updated);
  };

  const deleteRegion = () => {
      setRegions(regions.filter(r => r.id !== selectedRegionId));
      setSelectedRegionId(null);
  };

  const addColumn = () => {
      if (!selectedRegion) return;
      const cols = selectedRegion.columns || [];
      const newCol: ColumnDef = { x: 50, name: `Col ${cols.length + 1}`, type: 'string' };
      updateRegion('columns', [...cols, newCol]);
  };

  const updateColumn = (idx: number, field: keyof ColumnDef, val: any) => {
      if (!selectedRegion?.columns) return;
      const newCols = [...selectedRegion.columns];
      newCols[idx] = { ...newCols[idx], [field]: val };
      updateRegion('columns', newCols);
  };

  const removeColumn = (idx: number) => {
      if (!selectedRegion?.columns) return;
      updateRegion('columns', selectedRegion.columns.filter((_, i) => i !== idx));
  };


  return (
    <div className="fixed inset-0 bg-canvas z-50 overflow-y-auto">
      <div className="max-w-7xl mx-auto p-8">

        {/* Main Header */}
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            {view === 'edit' && (
                <button onClick={() => setView('list')} className="p-2 bg-white rounded-full shadow-sm hover:bg-slate-50 transition-colors">
                    <ChevronLeft size={20} />
                </button>
            )}
            <div>
                <h1 className="text-3xl font-bold tracking-tight">Parser Builder</h1>
                <p className="text-txt-secondary">
                    {view === 'list' ? 'Manage your extraction templates.' : 'Design and test your extraction layout.'}
                </p>
            </div>
          </div>
          <div className="flex gap-4">
            {view === 'edit' && (
                <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl shadow-sm border border-slate-100">
                    <span className="text-xs font-bold text-slate-400 uppercase">Template Name:</span>
                    <input 
                        type="text" 
                        value={templateName}
                        onChange={(e) => setTemplateName(e.target.value)}
                        className="font-bold text-slate-800 outline-none w-48"
                        placeholder="e.g. My Bank Statement"
                    />
                </div>
            )}
            {view === 'edit' && (
                <button onClick={handleSaveTemplate} className="flex items-center gap-2 px-6 py-2 bg-slate-900 text-white rounded-xl font-bold hover:scale-105 transition-transform">
                    <Save size={18} /> Save
                </button>
            )}
            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full">
              <X size={24} />
            </button>
          </div>
        </div>

        {/* LIST VIEW */}
        {view === 'list' && (
            <div className="bg-surface rounded-[32px] shadow-soft p-8">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold">Saved Templates</h3>
                    <button onClick={handleNewTemplate} className="flex items-center gap-2 px-6 py-3 bg-primary-start text-white font-bold rounded-xl hover:bg-primary-end transition-colors shadow-lg">
                        <Plus size={18} /> New Template
                    </button>
                </div>

                {templates.length === 0 ? (
                    <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                        <ListIcon size={48} className="mx-auto text-slate-300 mb-4" />
                        <p className="text-slate-500 font-bold">No templates found.</p>
                        <p className="text-slate-400 text-sm">Create one to get started.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {templates.map(t => (
                            <div key={t.id} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all group">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="p-3 bg-slate-50 rounded-xl text-slate-400 group-hover:text-primary-start group-hover:bg-primary-start/10 transition-colors">
                                        <FileText size={24} />
                                    </div>
                                    <div className="flex gap-2">
                                        <button onClick={() => handleEditTemplate(t)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"><Edit size={16} /></button>
                                        <button onClick={() => handleDeleteTemplate(t.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 size={16} /></button>
                                    </div>
                                </div>
                                <h4 className="font-bold text-lg mb-1">{t.name}</h4>
                                <p className="text-xs text-slate-400 font-mono mb-4">ID: {t.id.substr(0,8)}...</p>
                                <div className="flex gap-2">
                                    <span className="text-[10px] font-bold bg-slate-100 px-2 py-1 rounded text-slate-500">{t.regions?.length || 0} Zones</span>
                                    <span className="text-[10px] font-bold bg-slate-100 px-2 py-1 rounded text-slate-500">{t.page_strategy?.mode}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* EDITOR VIEW */}
        {view === 'edit' && (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Controls Sidebar */}
            <div className="lg:col-span-1 space-y-6">

                {/* 0. File Upload */}
                <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
                    <h3 className="font-bold mb-4 flex items-center gap-2"><FileText size={16} /> Sample Document</h3>
                    <input 
                        type="file" 
                        onChange={(e) => {
                            setTestFile(e.target.files ? e.target.files[0] : null);
                            setDebugImage(null);
                            // Do not clear regions on file change, we want to test the template against new files
                        }}
                        className="w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-slate-100 file:text-slate-700 hover:file:bg-slate-200"
                    />
                    {testFile && <p className="text-xs text-emerald-600 mt-2 font-bold">Loaded: {testFile.name}</p>}

                    <div className="flex items-center justify-between mt-4 bg-slate-50 p-2 rounded-xl">
                        <button 
                            onClick={() => setCurrentPage(Math.max(0, currentPage - 1))}
                            disabled={currentPage === 0}
                            className="p-2 hover:bg-white rounded-lg disabled:opacity-30"
                        >
                            <ChevronLeft size={16} />
                        </button>
                        <span className="text-xs font-bold font-mono">Page {currentPage + 1} of {pageCount}</span>
                        <button 
                            onClick={() => setCurrentPage(Math.min(pageCount - 1, currentPage + 1))}
                            disabled={currentPage >= pageCount - 1}
                            className="p-2 hover:bg-white rounded-lg disabled:opacity-30"
                        >
                            <ChevronRight size={16} />
                        </button>
                    </div>

                    <button 
                        onClick={handleTestExtraction}
                        disabled={!testFile || isLoading}
                        className="w-full mt-4 py-3 bg-slate-900 text-white font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-colors shadow-lg text-sm"
                    >
                        {isLoading ? <span className="animate-spin">⟳</span> : <Play size={16} />} Refresh Preview
                    </button>
                </div>

                {/* 1. Page Strategy */}
                <div className="bg-surface p-6 rounded-2xl shadow-soft border border-slate-100">
                    <h3 className="font-bold mb-4 flex items-center gap-2"><Settings size={16} /> Page Strategy</h3>
                    <div className="space-y-3">
                        <div>
                            <label className="text-xs font-bold uppercase text-txt-secondary">Identify Pages By</label>
                            <select 
                                value={pageStrategy.mode} 
                                onChange={(e) => setPageStrategy({...pageStrategy, mode: e.target.value})}
                                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-medium"
                            >
                                <option value="all">All Pages (Standard)</option>
                                <option value="regex">Text Match (Regex)</option>
                                <option value="first">First Page Only</option>
                            </select>
                        </div>
                        {pageStrategy.mode === 'regex' && (
                            <div>
                                <label className="text-xs font-bold uppercase text-txt-secondary">Regex Pattern</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. Data entrata.*" 
                                    value={pageStrategy.regex}
                                    onChange={(e) => setPageStrategy({...pageStrategy, regex: e.target.value})}
                                    className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-mono"
                                />
                            </div>
                        )}
                        <div>
                            <label className="text-xs font-bold uppercase text-txt-secondary">Stop Condition (Text)</label>
                            <input 
                                type="text" 
                                placeholder="e.g. Totale Netto" 
                                value={pageStrategy.stopCondition}
                                onChange={(e) => setPageStrategy({...pageStrategy, stopCondition: e.target.value})}
                                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm"
                            />
                        </div>
                    </div>
                </div>

                {/* Selected Region Editor OR Instructions */}
                {selectedRegion ? (
                    <div className="bg-surface p-6 rounded-2xl shadow-soft border-2 border-primary-start/20 animate-in slide-in-from-left-2">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold flex items-center gap-2 text-primary-start">
                                <MousePointer2 size={16} /> Edit Region
                            </h3>
                            <button onClick={deleteRegion} className="text-rose-400 hover:text-rose-600"><Trash2 size={16} /></button>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-xs font-bold uppercase text-txt-secondary">Region Name</label>
                                <input 
                                    type="text" 
                                    value={selectedRegion.name} 
                                    onChange={(e) => updateRegion('name', e.target.value)}
                                    className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm font-bold"
                                />
                            </div>
                            <div>
                                <label className="text-xs font-bold uppercase text-txt-secondary">Extraction Type</label>
                                <select 
                                    value={selectedRegion.type} 
                                    onChange={(e) => updateRegion('type', e.target.value)}
                                    className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg p-2 text-sm"
                                >
                                    <option value="text">Raw Text Block</option>
                                    <option value="table">Structured Table</option>
                                    <option value="key_value">Key-Value Pairs</option>
                                </select>
                            </div>

                            {selectedRegion.type === 'table' && (
                                <div className="border-t border-slate-100 pt-4">
                                    <label className="text-xs font-bold uppercase text-txt-secondary mb-2 block">Table Columns</label>
                                    <div className="space-y-2 max-h-40 overflow-y-auto">
                                        {(selectedRegion.columns || []).map((col, idx) => (
                                            <div key={idx} className="flex gap-2">
                                                <input 
                                                    type="number" 
                                                    value={col.x} 
                                                    onChange={(e) => updateColumn(idx, 'x', parseInt(e.target.value))} 
                                                    className="w-16 bg-slate-50 border rounded px-1 text-xs font-mono"
                                                    placeholder="X"
                                                />
                                                <input 
                                                    type="text" 
                                                    value={col.name} 
                                                    onChange={(e) => updateColumn(idx, 'name', e.target.value)} 
                                                    className="flex-1 bg-slate-50 border rounded px-1 text-xs"
                                                    placeholder="Name"
                                                />
                                                <button onClick={() => removeColumn(idx)} className="text-rose-400"><X size={12} /></button>
                                            </div>
                                        ))}
                                    </div>
                                    <button onClick={addColumn} className="mt-2 text-xs font-bold text-emerald-600 flex items-center gap-1">+ Add Col</button>
                                </div>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-300 text-center text-slate-400">
                        <MousePointer2 size={32} className="mx-auto mb-2 opacity-50" />
                        <p className="text-sm font-bold">Select a region to edit</p>
                        <p className="text-xs mt-1">Click and drag on the document to create a new extraction zone.</p>
                    </div>
                )}

                {/* Results JSON */}
                {Object.keys(previewData).length > 0 && (
                    <div className="bg-white border border-slate-200 rounded-2xl p-4 shadow-soft max-h-64 overflow-y-auto">
                        <h4 className="text-xs font-bold uppercase text-slate-400 mb-2">Extracted Data (Page {currentPage + 1})</h4>
                        <pre className="text-[10px] font-mono whitespace-pre-wrap text-slate-700">
                            {JSON.stringify(previewData, null, 2)}
                        </pre>
                    </div>
                )}
            </div>

            {/* Canvas Area */}
            <div className="lg:col-span-2 bg-slate-200 rounded-[32px] min-h-[800px] flex items-center justify-center border-4 border-dashed border-slate-300 relative overflow-hidden p-8 select-none">
                <div 
                    ref={canvasRef}
                    className="bg-white shadow-2xl relative cursor-crosshair transition-all"
                    style={{ width: '595px', height: '842px' }} // A4 Ratio approximation
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                >
                    {/* Background Image */}
                    {debugImage ? (
                        <img src={`data:image/png;base64,${debugImage}`} className="absolute inset-0 w-full h-full" />
                    ) : (
                        <div className="absolute inset-0 flex items-center justify-center text-slate-300 font-bold text-xl">
                            Upload a file to start
                        </div>
                    )}

                    {/* Drawn Regions */}
                    {regions.map((r) => (
                        <div
                            key={r.id}
                            className={`absolute border-2 region-box group ${selectedRegionId === r.id ? 'border-primary-start bg-primary-start/10 z-20' : 'border-slate-400/50 hover:border-slate-600 bg-white/10 z-10'}`}
                            style={{
                                left: `${r.x}%`,
                                top: `${r.y}%`,
                                width: `${r.w}%`,
                                height: `${r.h}%`
                            }}
                            onClick={(e) => {
                                e.stopPropagation();
                                setSelectedRegionId(r.id);
                            }}
                        >
                            {/* Label Tag */}
                            <div className={`absolute -top-6 left-0 px-2 py-0.5 rounded text-[10px] font-bold text-white whitespace-nowrap shadow-sm ${selectedRegionId === r.id ? 'bg-primary-start' : 'bg-slate-500'}`}>
                                {r.name} ({r.type})
                            </div>

                            {/* Visual Column Lines for Tables */}
                            {r.type === 'table' && r.columns?.map((col, i) => (
                                <div 
                                    key={i}
                                    className="absolute top-0 bottom-0 border-l border-dashed border-purple-500/80"
                                    style={{ left: `${col.x}px` }} 
                                ></div>
                            ))}
                        </div>
                    ))}

                    {/* Active Drawing Rect */}
                    {isDrawing && (
                        <div 
                            className="absolute border-2 border-dashed border-emerald-500 bg-emerald-500/10 pointer-events-none z-30"
                            style={{
                                left: currentRect.x,
                                top: currentRect.y,
                                width: currentRect.w,
                                height: currentRect.h
                            }}
                        ></div>
                    )}
                </div>
            </div>
            </div>
        )}
      </div>
    </div>
  );
};

